function escapeAttr(value) { return escapeHtml(value).replace(/`/g, '&#96;'); }
function formatDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }); }
function formatMoney(value, currency = 'BDT') { const number = Number(value || 0); return `${currency === 'BDT' ? '৳' : currency + ' '}${number.toLocaleString('en-BD', { maximumFractionDigits: 2 })}`; }
function displayName(user) { return user?.fullName || user?.email || user?.phone || user?.id || 'Unknown'; }
function initials(user) { return (displayName(user).replace(/[^a-zA-Z0-9 ]/g, '').split(/\s+/).map(part => part[0]).join('').slice(0, 2) || 'ST').toUpperCase(); }
function statusPill(status) { return `<span class="status-pill status-${escapeAttr(status)}">${escapeHtml(String(status || 'unknown').replace(/_/g, ' '))}</span>`; }
function emptyState(title, message, iconName = 'grid') { return `<div class="empty-state"><div class="empty-icon">${icon(iconName)}</div><strong>${escapeHtml(title)}</strong><p>${escapeHtml(message)}</p></div>`; }
function loadingState() { return '<div class="loading-state"><span class="spinner"></span>Loading workspace data…</div>'; }
function renderError(error, retryRoute = '') { return `<div class="error-state"><span>${escapeHtml(error?.message || 'Unable to load this section.')}</span>${retryRoute ? `<button class="admin-secondary" data-route="${escapeAttr(retryRoute)}">Retry</button>` : ''}</div>`; }
function safeRequest(path, options = {}) { return $admin(path, options).catch(error => ({ __error: error })); }
async function uploadMediaFile(file, folder, altText = '') { const form = new FormData(); form.append('file', file); form.append('folder', folder); form.append('altText', altText); const response = await $admin('/admin/media', { method: 'POST', body: form }); return response.media; }
function mediaFolderFor(type) { return ({ banner: 'banners', tour: 'tours', hotel: 'hotels', home: 'homes', destination: 'destinations', visa: 'services', esim: 'services', airline: 'services', homepage: 'general', offer: 'banners', faq: 'general', company: 'logos' })[type] || 'general'; }
function isError(value) { return value && value.__error; }
function markDirty(value = true) { state.unsaved = value; }
function resetDirty() { state.unsaved = false; }
function hasPermission(permission) { return state.permissions.has(permission); }
function roleLabel(role) { return String(role || '').replace(/_/g, ' '); }

function toast(message, type = '') { const region = $('#adminToast'); if (!region) return; const node = document.createElement('div'); node.className = `admin-toast ${type}`; node.textContent = message; region.appendChild(node); setTimeout(() => node.remove(), 4200); }
function setLoading(button, loading, label = 'Please wait…') { if (!button) return; button.disabled = loading; if (!button.dataset.originalText) button.dataset.originalText = button.textContent; button.textContent = loading ? label : button.dataset.originalText; }
function hydrateIcons(scope = document) { $$('[data-icon]', scope).forEach(node => { node.innerHTML = icon(node.dataset.icon); }); }

function initAuthScene() {
  const canvas = $('#authScene'); const card = $('#adminLoginCard'); const THREE = window.THREE;
  if (!canvas || !card || !THREE || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  try {
    const scene = new THREE.Scene(); const camera = new THREE.PerspectiveCamera(42, 1, .1, 100); camera.position.z = 8;
    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, powerPreference: 'low-power' }); renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    const group = new THREE.Group(); scene.add(group); const count = 150; const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i += 1) { positions[i * 3] = (Math.random() - .5) * 9; positions[i * 3 + 1] = (Math.random() - .5) * 8; positions[i * 3 + 2] = (Math.random() - .5) * 5; }
    const geometry = new THREE.BufferGeometry(); geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3)); const particles = new THREE.Points(geometry, new THREE.PointsMaterial({ color: 0x7192ff, size: .035, transparent: true, opacity: .6 })); group.add(particles);
    const blue = new THREE.MeshBasicMaterial({ color: 0x3864df, wireframe: true, transparent: true, opacity: .22 }); const gold = new THREE.MeshBasicMaterial({ color: 0xf4b64a, wireframe: true, transparent: true, opacity: .25 });
    const shapes = [new THREE.Mesh(new THREE.IcosahedronGeometry(.55, 1), blue), new THREE.Mesh(new THREE.OctahedronGeometry(.42, 0), gold), new THREE.Mesh(new THREE.TorusGeometry(.55, .012, 8, 32), blue), new THREE.Mesh(new THREE.BoxGeometry(.6, .6, .6), gold)];
    shapes.forEach((shape, index) => { shape.position.set([-2.7, 2.4, -2.1, 2.2][index], [1.8, -1.8, 2.2, -2.3][index], [-.2, .5, -.4, .7][index]); group.add(shape); });
    const pointer = { x: 0, y: 0 }; const resize = () => { const rect = card.getBoundingClientRect(); renderer.setSize(Math.max(1, rect.width), Math.max(1, rect.height), false); camera.aspect = rect.width / Math.max(rect.height, 1); camera.updateProjectionMatrix(); };
    card.addEventListener('pointermove', event => { const rect = card.getBoundingClientRect(); pointer.x = (event.clientX - rect.left) / rect.width * 2 - 1; pointer.y = -((event.clientY - rect.top) / rect.height * 2 - 1); card.style.setProperty('--tilt-x', `${pointer.x * 2.2}deg`); card.style.setProperty('--tilt-y', `${pointer.y * 2.2}deg`); card.classList.add('tilt-ready'); });
    card.addEventListener('pointerleave', () => { pointer.x = 0; pointer.y = 0; card.style.setProperty('--tilt-x', '0deg'); card.style.setProperty('--tilt-y', '0deg'); }); window.addEventListener('resize', resize); resize();
    const clock = new THREE.Clock(); let frame = 0; const animate = () => { frame = requestAnimationFrame(animate); if (document.hidden) return; const time = clock.getElapsedTime(); group.rotation.y += .0008; group.rotation.x = Math.sin(time * .18) * .045 + pointer.y * .035; group.position.x += (pointer.x * .18 - group.position.x) * .025; group.position.y += (pointer.y * .14 - group.position.y) * .025; shapes.forEach((shape, index) => { shape.rotation.x += .0015 + index * .0003; shape.rotation.y += .002 + index * .0002; }); renderer.render(scene, camera); }; animate();
    window.addEventListener('pagehide', () => { cancelAnimationFrame(frame); geometry.dispose(); particles.material.dispose(); shapes.forEach(shape => { shape.geometry.dispose(); shape.material.dispose(); }); renderer.dispose(); });
  } catch { /* Decorative WebGL may be unavailable; authentication remains functional. */ }
}
function stopCountdown(kind = 'admin') { const key = kind === 'admin' ? 'adminOtpTimer' : 'otpTimer'; if (state[key]) clearInterval(state[key]); state[key] = null; }
let firebaseAuthInstance = null;

async function ensureFirebaseAuth() {
  if (firebaseAuthInstance) return firebaseAuthInstance;
  const config = await $admin('/site/firebase-config', {}, false);
  if (!config || !config.configured || !config.firebase || !config.firebase.apiKey) throw Object.assign(new Error('Google sign-in is not configured for this deployment.'), { code: 'FIREBASE_NOT_CONFIGURED' });
  if (!window.firebase || !window.firebase.auth) throw Object.assign(new Error('Google sign-in libraries failed to load.'), { code: 'FIREBASE_SDK_MISSING' });
  const app = window.firebase.apps.length ? window.firebase.apps[0] : window.firebase.initializeApp(config.firebase);
  firebaseAuthInstance = window.firebase.auth(app);
  try { firebaseAuthInstance.useDeviceLanguage(); } catch { /* best effort */ }
  return firebaseAuthInstance;
}

async function loginWithGoogle() {
  const button = $('#googleSignInButton');
  const label = button?.querySelector('span');
  if (button) { button.disabled = true; button.classList.add('is-loading'); }
  if (label) label.textContent = 'Signing in…';
  try {
    const auth = await ensureFirebaseAuth();
    const provider = new window.firebase.auth.GoogleAuthProvider();
    provider.setCustomParameters({ prompt: 'select_account' });
    const result = await auth.signInWithPopup(provider);
    const idToken = await result.user.getIdToken();
    await $admin('/auth/firebase-login', { method: 'POST', body: JSON.stringify({ idToken }) });
    await loadWorkspace(true);
  } catch (error) {
    if (error?.code === 'auth/popup-closed-by-user') { /* user dismissed the popup — stay silent */ }
    else if (error?.code === 'auth/cancelled-popup-request' || error?.code === 'auth/popup-blocked') toast('Please allow pop-ups and try again.', 'error');
    else if (error?.code === 'ADMIN_NOT_REGISTERED') toast('This Google account is not an existing admin. Use email and password, or ask a Super Admin to create the account.', 'error');
    else if (error?.code === 'ADMIN_NOT_WHITELISTED') toast('This Google account is not authorized for admin access.', 'error');
    else if (error?.code === 'FIREBASE_EMAIL_NOT_VERIFIED') toast('Your Google account email is not verified.', 'error');
    else if (error?.code === 'FIREBASE_NOT_CONFIGURED' || error?.code === 'FIREBASE_SDK_MISSING') toast(error.message || 'Google sign-in is not configured.', 'error');
    else if (error?.code === 'ACCOUNT_UNAVAILABLE') toast(error.message || 'This account is suspended or disabled.', 'error');
    else if (error?.code && String(error.code).startsWith('auth/')) toast('Google sign-in failed. Please try again.', 'error');
    else toast(error?.message || 'Unable to sign in with Google.', 'error');
  } finally {
    if (button) { button.disabled = false; button.classList.remove('is-loading'); }
    if (label) label.textContent = 'Continue with Google';
  }
}

async function loginWithPassword(event) {
  event?.preventDefault?.();
  const button = $('#adminPasswordSignIn');
  const email = $('#adminLoginEmail')?.value.trim();
  const password = $('#adminLoginPassword')?.value;
  if (!email || !password) { toast('Enter your email and password.', 'error'); return; }
  setLoading(button, true, 'Signing in…');
  try {
    await $admin('/auth/password-login', { method: 'POST', body: JSON.stringify({ identity: email, password }) });
    await loadWorkspace(true);
  } catch (error) {
    toast(error?.message || 'Invalid admin email or password.', 'error');
  } finally { setLoading(button, false); }
}

async function logout() { await $admin('/auth/logout', { method: 'POST' }).catch(() => undefined); state.currentAdmin = null; state.permissions.clear(); location.href = '/admin'; }
function bindAuth() {
  $('#googleSignInButton')?.addEventListener('click', loginWithGoogle);
  $('#adminPasswordForm')?.addEventListener('submit', loginWithPassword);
  $('#adminPasswordToggle')?.addEventListener('click', () => {
    const field = $('#adminLoginPassword');
    if (!field) return;
    const show = field.type === 'password';
    field.type = show ? 'text' : 'password';
    $('#adminPasswordToggle').textContent = show ? 'Hide' : 'Show';
  });
}

function hasFineNav(value){ return value && state.finePermissions && state.finePermissions.has(String(value).replace(/_/g,'.')); }
async function loadNavigation() { const response = await safeRequest('/admin/navigation'); if (isError(response)) return false; const items = response.navigation || []; const grouped = new Map(); items.filter(item => {
      if (!item.visible || !item.enabled) return false;
      if (state.isSuperAdmin) return true;
      if (!item.permission || hasPermission(item.permission) || hasFineNav(item.permission) || hasFineNav(item.route)) return true;
      const routeFine = { '/admin/hotels':'hotel.view', '/admin/hotel-bookings':'booking.view', '/admin/travel-agents':'agent.view', '/admin/tours':'tour.view' }[item.route];
      return routeFine ? state.finePermissions.has(routeFine) : false;
    }).sort((a,b)=>a.sortOrder-b.sortOrder).forEach(item => { if(!grouped.has(item.groupName)) grouped.set(item.groupName,[]); grouped.get(item.groupName).push(item); }); const nav=$('#adminNav'); if(!nav)return true; nav.innerHTML=[...grouped.entries()].map(([group,entries])=>`<div class="nav-group" data-nav-group="${escapeAttr(group)}"><p>${escapeHtml(group)}</p>${entries.map(item=>`<a href="${escapeAttr(item.route)}" data-route="${escapeAttr(item.route)}" data-permission="${escapeAttr(item.permission||'')}" data-nav-id="${escapeAttr(item.id)}"><span data-icon="${escapeAttr(item.icon)}"></span><span>${escapeHtml(item.label)}</span></a>`).join('')}</div>`).join(''); hydrateIcons(nav); if (!state.isSuperAdmin) $$('#adminNav a[data-route="/admin/admins"]').forEach(link => link.remove()); return true; }
function isMobileView() { return window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT}px)`).matches; }
function currentHref() { return `${location.pathname}${location.search}`; }
function currentRoute() { const url = new URL(location.href); const path = url.pathname.replace(/^\/admin\/?/, '').replace(/\/$/, '') || 'dashboard'; return { url, path, query: url.searchParams }; }
function routeHref(path) { const value = path.startsWith('/admin') ? path : `/admin/${path.replace(/^\//, '')}`; return value || '/admin'; }
function canLeavePage() { if (!state.unsaved) return true; const leave = window.confirm('You have unsaved changes. Leave this page?'); if (leave) resetDirty(); return leave; }
function navigate(path, replace = false) {
  if (!canLeavePage()) return false;
  const href = routeHref(path);
  if (href === currentHref()) { updateNavigation(currentRoute()); if (isMobileView()) closeSidebar(); return false; }
  if (state.pendingHref === href) return false;
  state.pendingHref = href;
  if (replace) history.replaceState({}, '', href); else history.pushState({}, '', href);
  state.lastUrl = href;
  // The URL and active state are committed immediately. Data loading is independent of drawer state.
  updateNavigation(currentRoute());
  if (isMobileView()) closeSidebar();
  void renderRoute().finally(() => { if (state.pendingHref === href) state.pendingHref = ''; });
  return true;
}
function updateNavigation(route) {
  const links = $$('#adminNav a[data-route]').filter(link => !link.hidden);
  const target = `${route.url.pathname}${route.url.search}`;
  let best = null; let bestScore = -1;
  for (const link of links) {
    const configured = link.dataset.route || link.getAttribute('href') || '';
    const url = new URL(configured, location.origin);
    const linkPath = url.pathname;
    let score = -1;
    if (url.search && `${linkPath}${url.search}` === target) score = 10000 + linkPath.length;
    else if (!url.search && (linkPath === '/admin' ? route.url.pathname === '/admin' || route.url.pathname === '/admin/' : route.url.pathname === linkPath || route.url.pathname.startsWith(`${linkPath}/`))) score = linkPath.length;
    if (score > bestScore) { bestScore = score; best = link; }
  }
  $$('#adminNav a[data-route]').forEach(link => link.classList.toggle('active', link === best));
  $$('#adminNav [data-permission]').forEach(link => { const permission = link.dataset.permission; link.hidden = Boolean(permission) && !hasPermission(permission); });
}
function updateBreadcrumb(route) { const labels = { dashboard: 'Overview', bookings: 'Bookings', flights: 'Flights', hotels: 'Hotels', homes: 'Homes', visa: 'Visa Applications', tours: 'Go Get Tour', esim: 'eSIM', services: 'Service Visibility', content: 'Website Content', media: 'Media Library', customers: 'Customers', payments: 'Payments', notifications: 'Notifications', support: 'Support Tickets', settings: 'Settings', users: 'Admin Users', 'audit-logs': 'Audit Logs', 'travel-agents': 'Travel Agents', hotels: 'Hotels', 'hotel-bookings': 'Hotel Bookings', admins: 'Admin Management', campaigns: 'Campaigns', profile: 'Profile & Security', navigation: 'Navigation Manager', 'system-status': 'System Status', analytics: 'Analytics' }; const key = route.path.split('/')[0]; const detail = route.path.split('/')[1]; const text = labels[key] || key; const breadcrumb = $('#adminBreadcrumbs'); breadcrumb.innerHTML = `<span>Admin</span><strong>${escapeHtml(text)}${detail && key !== 'bookings' && key !== 'customers' ? ` · ${escapeHtml(detail)}` : ''}</strong>`; }

function showApp() { closeSidebar(); $('#adminAuthScreen').hidden = true; $('#adminApp').hidden = false; $('#adminSidebar')?.setAttribute('aria-hidden', String(isMobileView())); document.body.classList.add('admin-logged-in'); }
async function loadWorkspace(fromLogin = false) { try { const response = await $admin('/admin/me'); state.currentAdmin = response.user; state.permissions = new Set(response.permissions || []); state.finePermissions = new Set(response.finePermissions || []); state.isSuperAdmin = response.isSuperAdmin === true || state.currentAdmin?.role === 'super_admin'; state.lastUrl = currentHref(); $('#profileAvatar').innerHTML = response.user.avatarUrl ? `<img src="${escapeAttr(response.user.avatarUrl)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%" />` : escapeHtml(initials(response.user)); $('#profileName').textContent = displayName(response.user); $('#profileRole').textContent = roleLabel(response.user.role); showApp(); await loadNavigation(); if (fromLogin) { $('#adminLoginCard').classList.add('auth-success'); await new Promise(resolve => setTimeout(resolve, 420)); } updateNavigation(currentRoute()); await renderRoute(); await refreshNotificationBadge(); } catch (error) { if (error.status !== 401) toast(error.message || 'Unable to load admin workspace.', 'error'); } }

function pageHeader(eyebrow, title, description, actions = '') { return `<div class="page-header"><div class="page-header-copy"><span class="admin-eyebrow">${escapeHtml(eyebrow)}</span><h1>${escapeHtml(title)}</h1><p>${escapeHtml(description)}</p></div><div class="page-actions">${actions}</div></div>`; }
function cardHeader(title, description = '', actions = '') { return `<div class="card-header"><div><h2>${escapeHtml(title)}</h2>${description ? `<p>${escapeHtml(description)}</p>` : ''}</div>${actions}</div>`; }
function pagination(page, pageCount, basePath) { return `<div class="pagination"><button class="admin-secondary" data-page="${Math.max(1, page - 1)}" data-page-base="${escapeAttr(basePath)}" ${page <= 1 ? 'disabled' : ''}>Previous</button><span>Page ${page} of ${pageCount}</span><button class="admin-secondary" data-page="${Math.min(pageCount, page + 1)}" data-page-base="${escapeAttr(basePath)}" ${page >= pageCount ? 'disabled' : ''}>Next</button></div>`; }
function jsonBlock(value) { return escapeHtml(JSON.stringify(value ?? {}, null, 2)); }
function statusChart(distribution, total) { if (!distribution?.length) return emptyState('No bookings yet', 'Booking status distribution will appear when customers make reservations.', 'briefcase'); return distribution.map(item => `<div class="status-row"><span>${escapeHtml(item.status)}</span><div><i style="width:${Math.max(4, Math.round(item.count / Math.max(1, total) * 100))}%"></i></div><strong>${item.count}</strong></div>`).join(''); }
function revenueChart(trend) { if (!trend?.length || !trend.some(item => item.revenueBdt > 0)) return emptyState('No paid revenue yet', 'Revenue activity will appear after a verified payment webhook.', 'card'); const max = Math.max(1, ...trend.map(item => item.revenueBdt)); return `<div class="chart-bars">${trend.map(item => `<div class="chart-bar-wrap"><span class="chart-bar-value">${escapeHtml(formatMoney(item.revenueBdt))}</span><div class="chart-bar" style="height:${Math.max(4, Math.round(item.revenueBdt / max * 100))}%"></div><span class="chart-bar-label">${escapeHtml(item.month)}</span></div>`).join('')}</div>`; }

async function renderSystemStatus(){const response=await safeRequest('/admin/system-status');if(isError(response))return renderError(response.__error,'/admin');const labels={database:'Database',cloudinary:'Cloudinary',email:'Email',sms:'SMS',payment:'Payment gateway',travelApi:'Travel API'};$('#adminOutlet').innerHTML=pageHeader('Operations','System status','Provider and database availability without exposing secrets.','<button class="admin-secondary" data-action="refresh-page">Refresh</button>')+`<section class="admin-card"><div class="service-visibility-grid">${Object.entries(response.services||{}).map(([key,item])=>`<div class="visibility-card"><span class="visibility-icon">${icon(key==='database'?'grid':key==='cloudinary'?'image':key==='email'?'mail':key==='sms'?'message':key==='payment'?'card':'globe')}</span><div class="visibility-copy"><strong>${labels[key]||key}</strong><small>Live configuration status</small><div style="margin-top:7px">${statusPill(item.status)}</div></div></div>`).join('')}</div></section>`;}
async function renderAnalytics() {
  const route = currentRoute();
  const range = ['today', '7d', '30d', '90d', 'year', 'custom'].includes(route.query.get('range') || '') ? route.query.get('range') : '30d';
  const from = route.query.get('from') || '';
  const to = route.query.get('to') || '';
  const response = await safeRequest(`/admin/analytics?range=${encodeURIComponent(range)}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
  if (isError(response)) return renderError(response.__error, '/admin/analytics');
  const report = response.report || {};
  const s = report.summary || {};
  const ranges = [['today', 'Today'], ['7d', '7 Days'], ['30d', '30 Days'], ['90d', '90 Days'], ['year', 'This Year']];
  const rangeNav = `<div class="range-nav">${ranges.map(([value, label]) => `<a class="range-btn ${range === value ? 'is-active' : ''}" href="/admin/analytics?range=${value}" data-route="/admin/analytics?range=${value}">${label}</a>`).join('')}<form class="range-custom" data-analytics-range><input type="date" name="from" value="${escapeAttr(from)}" max="${escapeAttr(todayInput())}" /><span>→</span><input type="date" name="to" value="${escapeAttr(to)}" max="${escapeAttr(todayInput())}" /><button class="admin-secondary" type="submit">Apply</button></form></div>`;
  const kpis = [
    { label: 'Visitors', value: s.visitors || 0, icon: 'users' }, { label: 'Page views', value: s.pageViews || 0, icon: 'eye' },
    { label: 'Searches', value: s.searches || 0, icon: 'globe' }, { label: 'Bookings created', value: s.bookingsCreated || 0, icon: 'briefcase' },
    { label: 'Bookings confirmed', value: s.bookingsConfirmed || 0, icon: 'check' }, { label: 'Payments started', value: s.paymentsStarted || 0, icon: 'card' },
    { label: 'Payments success', value: s.paymentsSuccess || 0, icon: 'check' }, { label: 'Payments failed', value: s.paymentsFailed || 0, icon: 'close' },
    { label: 'Conversion rate', value: `${s.conversionRate || 0}%`, icon: 'activity' }, { label: 'Payment conversion', value: `${s.paymentConversionRate || 0}%`, icon: 'activity' }
  ];
  const trend = report.trend || [];
  const maxViews = Math.max(1, ...trend.map(item => item.pageViews || 0));
  const trendChart = trend.length
    ? `<div class="chart-bars chart-bars-trend">${trend.map(item => `<div class="chart-bar-wrap"><span class="chart-bar-value">${item.pageViews || 0}</span><div class="chart-bar" style="height:${Math.max(4, Math.round((item.pageViews || 0) / maxViews * 100))}%" title="${escapeAttr(`${item.day} · ${item.pageViews} views · ${item.visitors} visitors · ${item.conversions} conversions`)}"></div><span class="chart-bar-label">${escapeHtml(item.day.slice(5))}</span></div>`).join('')}</div>`
    : emptyState('No traffic yet', 'Page views appear as soon as visitors open the website.', 'activity');
  const deviceTotal = Math.max(1, (report.deviceBreakdown || []).reduce((sum, item) => sum + item.count, 0));
  const deviceRows = (report.deviceBreakdown || []).length
    ? report.deviceBreakdown.map(item => `<div class="status-row"><span>${escapeHtml(item.device)}</span><div><i style="width:${Math.max(4, Math.round(item.count / deviceTotal * 100))}%"></i></div><strong>${item.count}</strong></div>`).join('')
    : emptyState('No devices yet', 'Device data appears with the first page views.', 'eye');
  $('#adminOutlet').innerHTML = pageHeader('Website analytics', 'Analytics', 'Real business events — page views, searches, bookings and payments — measured without counting every refresh as a conversion.', '<button class="admin-secondary" data-action="refresh-page">Refresh</button>') +
    rangeNav +
    `<section class="kpi-grid">${kpis.map(item => `<div class="kpi-card"><span class="kpi-icon">${icon(item.icon)}</span><small>${escapeHtml(item.label)}</small><strong>${escapeHtml(item.value)}</strong></div>`).join('')}</section>` +
    `<div class="dashboard-grid"><section class="admin-card span-full">${cardHeader('Traffic trend', `${report.from ? new Date(report.from).toLocaleDateString() : ''} — ${report.to ? new Date(report.to).toLocaleDateString() : ''} · daily page views`)}${trendChart}</section>` +
    `<section class="admin-card">${cardHeader('Popular pages', 'Most viewed storefront routes')}<div class="recent-list">${(report.topPages || []).slice(0, 8).map(item => `<div class="recent-item"><span class="recent-main"><strong>${escapeHtml(item.path)}</strong><small>${item.visitors} visitors</small></span><strong>${item.views}</strong></div>`).join('') || emptyState('No page data yet', 'Popular pages appear after visitors browse the website.', 'eye')}</div></section>` +
    `<section class="admin-card">${cardHeader('Devices', 'Visitor device breakdown')}<div class="status-bars">${deviceRows}</div></section>` +
    `<section class="admin-card">${cardHeader('Top events', 'Tracked business events')}<div class="recent-list">${(report.topEvents || []).slice(0, 10).map(item => `<div class="recent-item"><span class="recent-main"><strong>${escapeHtml(item.event)}</strong></span><strong>${item.count}</strong></div>`).join('') || emptyState('No events yet', 'Tracked events appear here.', 'activity')}</div></section></div>`;
  hydrateIcons();
  $('#adminOutlet').querySelector('[data-action="refresh-page"]')?.addEventListener('click', () => void renderRoute());
  $('#adminOutlet').querySelector('[data-analytics-range]')?.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = new FormData(event.target);
    const next = new URLSearchParams({ range: 'custom' });
    if (data.get('from')) next.set('from', String(data.get('from')));
    if (data.get('to')) next.set('to', String(data.get('to')));
    window.history.pushState({}, '', `/admin/analytics?${next.toString()}`);
    void renderRoute();
  });
}
function todayInput() { return new Date().toISOString().slice(0, 10); }

async function renderDashboard() {
  const [stats, services, payments, tickets] = await Promise.all([safeRequest('/admin/stats'), safeRequest('/admin/services'), hasPermission('payments_view') ? safeRequest('/admin/payments?page=1&pageSize=6') : Promise.resolve({ payments: [] }), hasPermission('support_manage') ? safeRequest('/admin/tickets') : Promise.resolve({ tickets: [] })]);
  if (isError(stats)) return renderError(stats.__error, '/admin');
  const data = stats; const vertical = data.verticalCounts || {}; const bookings = data.bookings || {}; const serviceRows = isError(services) ? [] : (services.services || []); const recentPayments = isError(payments) ? [] : (payments.payments || []); const supportRows = isError(tickets) ? [] : (tickets.tickets || []);
  const kpis = [{ label: 'Total Bookings', value: bookings.total || 0, route: '/admin/bookings', icon: 'briefcase' }, { label: 'Needs Review', value: (bookings.new || 0) + (bookings.reviewing || 0) + (bookings.pending || 0), route: '/admin/bookings?status=needs_review', icon: 'clock' }, { label: 'Confirmed', value: (bookings.confirmed || 0) + (bookings.completed || 0), route: '/admin/bookings?status=confirmed', icon: 'check' }, { label: 'Customers', value: data.customers || 0, route: '/admin/customers', icon: 'users' }, { label: 'Paid Revenue', value: formatMoney(data.revenueBdt), route: '/admin/payments?status=paid', icon: 'card' }, { label: 'Flight Orders', value: vertical.flight || 0, route: '/admin/flights', icon: 'plane' }, { label: 'Hotel Orders', value: vertical.hotel || 0, route: '/admin/hotels', icon: 'hotel' }, { label: 'Home Orders', value: vertical.home || 0, route: '/admin/homes', icon: 'home' }, { label: 'Visa Applications', value: vertical.visa || 0, route: '/admin/visa', icon: 'passport' }, { label: 'eSIM Orders', value: vertical.esim || 0, route: '/admin/esim', icon: 'sim' }];
  const recentBookings = data.recentBookings || []; const activity = data.recentActivity || []; const openTickets = supportRows.filter(ticket => !['closed','resolved'].includes(ticket.status)).length;
  $('#adminOutlet').innerHTML = pageHeader('Operations overview', 'Dashboard', 'A live view of persisted bookings, customers, payments, content and support activity.', `<button class="admin-secondary" data-action="refresh-dashboard">Refresh data</button>`) + `<section class="kpi-grid">${kpis.map(item => `<a href="${escapeAttr(routeHref(item.route))}" data-route="${escapeAttr(routeHref(item.route))}" class="kpi-card"><span class="kpi-icon">${icon(item.icon)}</span><small>${escapeHtml(item.label)}</small><strong>${escapeHtml(item.value)}</strong><span class="kpi-arrow">↗</span></a>`).join('')}</section><div class="dashboard-grid"><section class="admin-card">${cardHeader('Revenue activity', 'Verified paid transactions from the last six months')} ${revenueChart(data.revenueTrend)}</section><section class="admin-card">${cardHeader('Booking status', 'Current lifecycle distribution')}<div class="status-bars">${statusChart(data.statusDistribution, bookings.total)}</div></section><section class="admin-card">${cardHeader('Recent bookings', 'Latest updates in the operations queue', '<a class="admin-secondary" href="/admin/bookings" data-route="/admin/bookings">View all</a>')}<div class="recent-list">${recentBookings.length ? recentBookings.slice(0, 8).map(item => `<a class="recent-item" href="/admin/bookings/${escapeAttr(item.id)}" data-route="/admin/bookings/${escapeAttr(item.id)}"><span class="recent-main"><strong>${escapeHtml(item.vertical)} · ${escapeHtml(displayName(item.customer))}</strong><small>${escapeHtml(item.id.slice(0, 12).toUpperCase())} · ${escapeHtml(formatDate(item.updatedAt))}</small></span>${statusPill(item.status)}</a>`).join('') : emptyState('No bookings yet', 'Bookings will appear here when customers make reservations.', 'briefcase')}</div></section><section class="admin-card">${cardHeader('Recent payments', 'Payment activity from the configured gateway', '<a class="admin-secondary" href="/admin/payments" data-route="/admin/payments">View all</a>')}<div class="recent-list">${recentPayments.length ? recentPayments.map(item => `<a class="recent-item" href="/admin/payments" data-route="/admin/payments"><span class="recent-main"><strong>${escapeHtml(displayName(item.customer))}</strong><small>${escapeHtml(item.provider)} · ${escapeHtml(formatDate(item.createdAt))}</small></span><span>${formatMoney(item.amount, item.currency)}</span>${statusPill(item.status)}</a>`).join('') : emptyState('No payments yet', 'Verified payment transactions will appear here.', 'card')}</div></section><section class="admin-card">${cardHeader('Recent activity', 'Admin and system audit trail', hasPermission('audit_view') ? '<a class="admin-secondary" href="/admin/audit-logs" data-route="/admin/audit-logs">Open logs</a>' : '')}<div class="activity-list">${activity.length ? activity.slice(0, 8).map(item => `<div class="activity-item"><span class="activity-dot"></span><div><strong>${escapeHtml(item.action.replace(/\./g, ' · '))}</strong><small>${escapeHtml(formatDate(item.createdAt))}</small></div></div>`).join('') : emptyState('No activity yet', 'Important actions will be recorded here.', 'activity')}</div></section><section class="admin-card">${cardHeader('Service status', 'Visibility is controlled independently from record retention', hasPermission('services_manage') ? '<a class="admin-secondary" href="/admin/services" data-route="/admin/services">Manage services</a>' : '')}<div class="service-summary">${serviceRows.map(item => `<a class="service-summary-item" href="/admin/services" data-route="/admin/services"><span class="service-summary-icon">${icon(item.icon)}</span><span><strong>${escapeHtml(item.label)}</strong><small>${statusPill(item.status)}</small></span></a>`).join('') || emptyState('No service settings yet', 'Service visibility will appear here.', 'settings')}</div></section><section class="admin-card">${cardHeader('Support summary', 'Customer care queue', '<a class="admin-secondary" href="/admin/support" data-route="/admin/support">Open support</a>')}<div class="support-summary-copy"><strong>${openTickets}</strong><span>open or in-progress tickets</span><p>${supportRows.length ? `${supportRows.length} total ticket records` : 'No support tickets yet.'}</p></div></section></div>`;
  hydrateIcons();
  $('#adminOutlet').querySelector('[data-action="refresh-dashboard"]')?.addEventListener('click', () => void renderRoute());
}

async function renderBookings() {
  const route = currentRoute(); const page = Number(route.query.get('page') || 1); const status = route.query.get('status') || ''; const vertical = route.query.get('vertical') || ''; const q = route.query.get('q') || ''; const query = new URLSearchParams({ page: String(page), pageSize: '20' }); if (q) query.set('q', q); if (status) query.set('status', status); if (vertical) query.set('vertical', vertical); const response = await safeRequest(`/admin/bookings?${query}`); if (isError(response)) return renderError(response.__error, '/admin/bookings');
  const rows = response.bookings || []; const statusOptions = ['needs_review','new','reviewing','accepted','processing','pending','confirmed','completed','rejected','cancelled','failed'];
  $('#adminOutlet').innerHTML = pageHeader('Operations queue', 'All bookings', 'Search and manage the complete customer booking lifecycle.', `<button class="admin-secondary" data-action="refresh-page">Refresh</button>`) + `<section class="admin-card"><form class="filter-bar" id="bookingFilterForm"><input class="filter-search" name="q" placeholder="Search booking ID, customer, phone or email" value="${escapeAttr(q)}" /><select class="filter-select" name="status"><option value="">All status</option>${statusOptions.map(item => `<option value="${item}" ${item === status ? 'selected' : ''}>${item.replace(/_/g, ' ')}</option>`).join('')}</select><select class="filter-select" name="vertical"><option value="">All services</option>${['flight','hotel','home','visa','tour','esim'].map(item => `<option value="${item}" ${item === vertical ? 'selected' : ''}>${item}</option>`).join('')}</select><button class="admin-primary" type="submit">Search</button></form><div class="table-wrap"><table><thead><tr><th>Booking ID</th><th>Customer</th><th>Service</th><th>Created</th><th>Status</th><th>Owner</th><th>Actions</th></tr></thead><tbody>${rows.length ? rows.map(item => `<tr><td><a class="table-link" href="/admin/bookings/${escapeAttr(item.id)}" data-route="/admin/bookings/${escapeAttr(item.id)}">${escapeHtml(item.id.slice(0, 12).toUpperCase())}</a><span class="table-secondary">${escapeHtml(item.id)}</span></td><td><span class="table-primary">${escapeHtml(displayName(item.customer))}</span><span class="table-secondary">${escapeHtml(item.customer?.phone || item.customer?.email || '')}</span></td><td>${escapeHtml(item.vertical)}</td><td>${escapeHtml(formatDate(item.createdAt))}</td><td>${statusPill(item.status)}</td><td>${escapeHtml(displayName(item.owner))}</td><td><div class="table-actions">${item.ownerId ? (item.ownerId === state.currentAdmin?.id || ['admin','super_admin'].includes(state.currentAdmin?.role) ? `<button class="table-action" data-booking-release="${escapeAttr(item.id)}">Release</button>` : '') : `<button class="table-action" data-booking-claim="${escapeAttr(item.id)}">Take</button>`}<a class="table-action" href="/admin/bookings/${escapeAttr(item.id)}" data-route="/admin/bookings/${escapeAttr(item.id)}">Open</a></div></td></tr>`).join('') : `<tr><td colspan="7">${emptyState('No bookings found', 'Try changing the filters or wait for a customer reservation.', 'briefcase')}</td></tr>`}</tbody></table></div>${pagination(response.page, response.pageCount, `/admin/bookings?${new URLSearchParams({ ...(q ? { q } : {}), ...(status ? { status } : {}), ...(vertical ? { vertical } : {}) }).toString()}`)}</section>`;
  bindBookingsPage();
}
function bindBookingsPage() { $('#bookingFilterForm')?.addEventListener('submit', event => { event.preventDefault(); const form = new FormData(event.currentTarget); const params = new URLSearchParams(); for (const [key, value] of form.entries()) if (value) params.set(key, value); navigate(`/admin/bookings?${params}`); }); $$('[data-booking-claim]').forEach(button => button.addEventListener('click', async event => { event.preventDefault(); event.stopPropagation(); button.disabled = true; try { await $admin(`/admin/bookings/${button.dataset.bookingClaim}/claim`, { method: 'POST' }); toast('Booking claimed.', 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to claim booking.', 'error'); button.disabled = false; } })); $$('[data-booking-release]').forEach(button => button.addEventListener('click', async event => { event.preventDefault(); event.stopPropagation(); button.disabled = true; try { await $admin(`/admin/bookings/${button.dataset.bookingRelease}/release`, { method: 'POST' }); toast('Booking released.', 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to release booking.', 'error'); button.disabled = false; } })); bindPagination(); $('#adminOutlet').querySelector('[data-action="export-payments"]')?.addEventListener('click', exportCsv); }

async function renderBookingDetail(id) { const [detail, users, payments] = await Promise.all([safeRequest(`/admin/bookings/${id}`), hasPermission('users_manage') ? safeRequest('/admin/users') : Promise.resolve({ users: [] }), hasPermission('payments_view') ? safeRequest(`/admin/payments?q=${encodeURIComponent(id)}&pageSize=10`) : Promise.resolve({ payments: [] })]); if (isError(detail)) return renderError(detail.__error, '/admin/bookings'); const booking = detail.booking; const team = isError(users) ? [] : (users.users || []).filter(user => user.role !== 'customer'); const paymentRows = isError(payments) ? [] : (payments.payments || []); const options = ['new','reviewing','accepted','processing','pending','confirmed','completed','rejected','cancelled','failed'];
  $('#adminOutlet').innerHTML = pageHeader('Booking workspace', booking.id.slice(0, 12).toUpperCase(), 'Review customer details, provider data and the full booking audit timeline.', `<button class="admin-secondary" data-route="/admin/bookings">Back to bookings</button>`) + `<div class="booking-detail-grid"><section class="admin-card">${cardHeader('Booking overview', `${booking.vertical} · created ${formatDate(booking.createdAt)}`)}<dl class="detail-list"><div><dt>Customer</dt><dd>${escapeHtml(displayName(booking.customer))}</dd></div><div><dt>Phone / email</dt><dd>${escapeHtml(booking.customer?.phone || booking.customer?.email || 'Not provided')}</dd></div><div><dt>Provider reference</dt><dd>${escapeHtml(booking.providerRef || 'Not assigned')}</dd></div><div><dt>Current owner</dt><dd>${escapeHtml(displayName(booking.owner))}</dd></div><div><dt>Created</dt><dd>${escapeHtml(formatDate(booking.createdAt))}</dd></div><div><dt>Updated</dt><dd>${escapeHtml(formatDate(booking.updatedAt))}</dd></div></dl><div class="detail-section"><h3>Customer actions</h3><div class="page-actions"><a class="admin-secondary" href="tel:${escapeAttr(booking.customer?.phone || '')}">Call customer</a><a class="admin-secondary" href="mailto:${escapeAttr(booking.customer?.email || '')}">Email customer</a></div></div><div class="detail-section"><h3>Request data</h3><textarea class="field-label" id="bookingRequestData" rows="10" style="width:100%;border:1px solid var(--admin-border-strong);border-radius:7px;padding:10px;font:inherit;font-size:11px">${jsonBlock(booking.request)}</textarea></div></section><section class="admin-card">${cardHeader('Workflow control', 'Changes are validated and recorded server-side')}<form id="bookingDetailForm"><label class="field-label"><span>Status</span><select id="bookingStatus">${options.map(option => `<option value="${option}" ${booking.status === option ? 'selected' : ''}>${option.replace(/_/g, ' ')}</option>`).join('')}</select></label><label class="field-label" style="margin-top:13px"><span>Assigned operator</span><select id="bookingOwner" ${hasPermission('bookings_manage') ? '' : 'disabled'}><option value="">Unassigned</option>${team.map(user => `<option value="${escapeAttr(user.id)}" ${user.id === booking.ownerId ? 'selected' : ''}>${escapeHtml(displayName(user))} · ${escapeHtml(roleLabel(user.role))}</option>`).join('')}</select></label><label class="field-label" style="margin-top:13px"><span>Internal note</span><textarea id="bookingInternalNote" rows="5" maxlength="4000">${escapeHtml(booking.internalNote || '')}</textarea></label><div class="form-actions"><span class="form-status" id="bookingSaveStatus"></span><button class="admin-primary" type="submit">Save changes</button></div></form><div class="detail-section"><h3>Payment information</h3>${paymentRows.length ? `<div class="recent-list">${paymentRows.map(payment => `<div class="recent-item"><span class="recent-main"><strong>${escapeHtml(payment.provider)}</strong><small>${escapeHtml(payment.transactionRef || payment.id)}</small></span><span>${formatMoney(payment.amount, payment.currency)}</span>${statusPill(payment.status)}</div>`).join('')}</div>` : emptyState('No payment records', 'Payment intents will appear once a gateway is configured.', 'card')}</div></section><section class="admin-card span-full">${cardHeader('Booking timeline', 'Every important state change is retained')}<div class="timeline">${detail.history?.length ? detail.history.map(item => `<div class="timeline-item"><strong>${escapeHtml(item.action.replace(/_/g, ' '))}${item.toStatus ? ` · ${escapeHtml(item.toStatus)}` : ''}</strong><small>${escapeHtml(formatDate(item.createdAt))}${item.note ? ` · ${escapeHtml(item.note)}` : ''}</small></div>`).join('') : emptyState('No timeline entries', 'Booking events will be shown here.', 'activity')}</div></section></div>`;
  $('#bookingDetailForm')?.addEventListener('submit', async event => { event.preventDefault(); const button = event.submitter; let request; try { request = JSON.parse($('#bookingRequestData').value); } catch { toast('Request data must be valid JSON.', 'error'); return; } if (!request || Array.isArray(request) || typeof request !== 'object') { toast('Request data must be a JSON object.', 'error'); return; } setLoading(button, true, 'Saving…'); try { await $admin(`/admin/bookings/${id}`, { method: 'PATCH', body: JSON.stringify({ status: $('#bookingStatus').value, internalNote: $('#bookingInternalNote').value.trim(), request, ...(hasPermission('bookings_manage') ? { ownerId: $('#bookingOwner').value || null } : {}) }) }); resetDirty(); toast('Booking updated successfully.', 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to save booking.', 'error'); } finally { setLoading(button, false); } });
}

