async function renderTours() { const route = currentRoute(); const q = route.query.get('q') || ''; const status = route.query.get('status') || ''; const response = await safeRequest(`/admin/tours?${new URLSearchParams({ ...(q ? { q } : {}), ...(status ? { status } : {}) })}`); if (isError(response)) return renderError(response.__error, '/admin/tours'); const tours = response.tours || []; $('#adminOutlet').innerHTML = pageHeader('Catalogue', 'Tour packages', 'Create, preview, publish and archive Go Get Tour packages without deleting historical records.', '<button class="admin-primary" data-action="new-tour">+ New tour package</button>') + `<section class="admin-card"><form class="filter-bar" id="tourFilterForm"><input class="filter-search" name="q" placeholder="Search title, country or destination" value="${escapeAttr(q)}" /><select name="status" class="filter-select"><option value="">All publication status</option><option value="draft" ${status === 'draft' ? 'selected' : ''}>Draft</option><option value="published" ${status === 'published' ? 'selected' : ''}>Published</option><option value="archived" ${status === 'archived' ? 'selected' : ''}>Archived</option></select><button class="admin-primary" type="submit">Search</button></form><div class="table-wrap"><table><thead><tr><th>Package</th><th>Type</th><th>Duration</th><th>Price</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${tours.length ? tours.map(tour => `<tr><td><span class="table-primary">${escapeHtml(tour.title)}</span><span class="table-secondary">${escapeHtml(tour.country)} · ${escapeHtml(tour.destinations.join(', '))}</span></td><td>${escapeHtml(tour.tourType)}</td><td>${tour.durationDays}D / ${tour.durationNights}N</td><td>${formatMoney(tour.priceBdt)}</td><td>${statusPill(tour.status)}</td><td>${escapeHtml(formatDate(tour.updatedAt))}</td><td><div class="table-actions"><button class="table-action" data-tour-edit="${escapeAttr(tour.id)}">Edit</button><button class="table-action" data-tour-preview="${escapeAttr(tour.id)}">Preview</button><button class="table-action" data-tour-duplicate="${escapeAttr(tour.id)}">Duplicate</button>${tour.status !== 'archived' ? `<button class="table-action danger" data-tour-archive="${escapeAttr(tour.id)}">Archive</button>` : ''}</div></td></tr>`).join('') : `<tr><td colspan="7">${emptyState('No tour packages yet', 'Create a package when you have a real itinerary and price to publish.', 'map')}</td></tr>`}</tbody></table></div></section>`; bindToursPage(tours); }
