  $$('[data-room-archive]').forEach(b => b.addEventListener('click', async () => { const room = rooms.find(r => r.id === b.dataset.roomArchive); if (!room || !(await confirmAction('Archive room?', `Archive “${room.name}”?`, 'Archive room'))) return; try { await $admin(`/admin/hotels/${hotel.id}/rooms/${room.id}`, { method: 'DELETE' }); toast('Room archived.', 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to archive room.', 'error'); } }));
  $$('[data-room-inventory]').forEach(b => b.addEventListener('click', e => { e.preventDefault(); openRoomInventory(hotel.id, b.dataset.roomInventory, rooms.find(r => r.id === b.dataset.roomInventory)); }));
