/* ============================================================
   SADIK TRAVELS — SUPER ADMIN: admin accounts & granular permissions
   ============================================================ */
let permissionCatalog = null;
let adminSelectedPerms = new Set();
let adminAvatarUrl = '';

async function ensurePermissionCatalog() {
  if (permissionCatalog) return permissionCatalog;
  try { const response = await safeRequest('/admin/permissions/catalog'); if (!isError(response)) permissionCatalog = response.catalog; } catch { /* offline fallback */ }
  return permissionCatalog || [];
}
function adminStatusPill(status) {
  const map = { active: ['status-active', 'Active'], suspended: ['status-pending', 'Suspended'], blocked: ['status-hidden', 'Disabled'], pending: ['status-pending', 'Pending'] };
  const [className, label] = map[status] || ['', 'Unknown'];
  return `<span class="status-pill ${className}">${escapeHtml(label)}</span>`;
}
function roleBadge(role) { return role === 'super_admin' ? '<span class="status-pill status-active">Super Admin</span>' : `<span class="status-pill">${escapeHtml(roleLabel(role))}</span>`; }

async function renderAdmins() {
  if (state.currentAdmin?.role !== 'super_admin') { $('#adminOutlet').innerHTML = pageHeader('Security', 'Admin Management', 'Create admins and assign granular permissions.', '') + `<section class="admin-card">${emptyState('Super Admin only', 'Only a Super Admin can manage admin accounts.', 'lock')}</section>`; return; }
  const response = await safeRequest('/admin/admins');
  if (isError(response)) return renderError(response.__error, '/admin/admins');
  const admins = response.admins || [];
  const rows = admins.length ? admins.map(admin => `<tr>
    <td><div class="media-thumb">${admin.avatarUrl ? `<img src="${escapeAttr(admin.avatarUrl)}" alt=""/>` : `<span>${escapeHtml(initials(admin))}</span>`}</div></td>
    <td><span class="table-primary">${escapeHtml(displayName(admin))}</span><span class="table-secondary">${escapeHtml(admin.email || '')}</span>${admin.id === state.currentAdmin?.id ? '<span class="table-secondary">· You</span>' : ''}</td>
    <td>${escapeHtml(admin.phone || '—')}</td>
    <td>${roleBadge(admin.role)}</td>
    <td>${adminStatusPill(admin.status)}</td>
    <td>${Array.isArray(admin.permissions) ? `<strong>${admin.permissions.length}</strong> <span class="table-secondary">custom</span>` : '<span class="table-secondary">Role default</span>'}</td>
    <td>${escapeHtml(formatDate(admin.lastLoginAt))}</td>
    <td><div class="table-actions"><button class="table-action" data-admin-edit="${escapeAttr(admin.id)}">Edit</button>${admin.role !== 'super_admin' ? `<button class="table-action" data-admin-perms="${escapeAttr(admin.id)}">Permissions</button><button class="table-action" data-admin-reset="${escapeAttr(admin.id)}">Reset password</button>${admin.status === 'active' ? `<button class="table-action" data-admin-suspend="${escapeAttr(admin.id)}">Suspend</button>` : `<button class="table-action" data-admin-activate="${escapeAttr(admin.id)}">Activate</button>`}<button class="table-action danger" data-admin-delete="${escapeAttr(admin.id)}">Delete</button>` : '<span class="table-secondary">Unrestricted</span>'}</div></td>
  </tr>`).join('') : `<tr><td colspan="8">${emptyState('No admins yet', 'Create an admin account to delegate access securely.', 'lock')}</td></tr>`;
  $('#adminOutlet').innerHTML = pageHeader('Security', 'Admin Management', 'Create admins, assign granular permissions and control account status. Permissions are enforced on every protected API endpoint.', '<button class="admin-primary" data-action="new-admin">+ Add admin</button>') + `<section class="admin-card"><div class="table-wrap"><table><thead><tr><th></th><th>Admin</th><th>Phone</th><th>Role</th><th>Status</th><th>Permissions</th><th>Last login</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
  bindAdminsPage(admins);
}
function bindAdminsPage(admins) {
  $('#adminOutlet').querySelector('[data-action="new-admin"]')?.addEventListener('click', () => openAdminEditor());
  $$('[data-admin-edit]').forEach(button => button.addEventListener('click', () => openAdminEditor(admins.find(admin => admin.id === button.dataset.adminEdit))));
  $$('[data-admin-perms]').forEach(button => button.addEventListener('click', () => openAdminEditor(admins.find(admin => admin.id === button.dataset.adminPerms), true)));
  $$('[data-admin-reset]').forEach(button => button.addEventListener('click', () => openResetPasswordModal(admins.find(admin => admin.id === button.dataset.adminReset))));
  $$('[data-admin-suspend]').forEach(button => button.addEventListener('click', async () => { const admin = admins.find(a => a.id === button.dataset.adminSuspend); if (admin && (await confirmAction('Suspend admin?', `${displayName(admin)} will be signed out and cannot login until reactivated.`, 'Suspend'))) await setAdminStatus(admin, 'suspended'); }));
  $$('[data-admin-activate]').forEach(button => button.addEventListener('click', () => setAdminStatus(admins.find(admin => admin.id === button.dataset.adminActivate), 'active')));
  $$('[data-admin-delete]').forEach(button => button.addEventListener('click', async () => { const admin = admins.find(a => a.id === button.dataset.adminDelete); if (admin && (await confirmAction('Delete admin?', `Permanently delete ${displayName(admin)}? This cannot be undone.`, 'Delete admin'))) { try { await $admin(`/admin/admins/${admin.id}`, { method: 'DELETE' }); toast('Admin deleted.', 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to delete admin.', 'error'); } } }));
}
async function setAdminStatus(admin, status) { try { await $admin(`/admin/admins/${admin.id}/status`, { method: 'POST', body: JSON.stringify({ status }) }); toast(`Admin ${status === 'active' ? 'activated' : status === 'suspended' ? 'suspended' : 'disabled'}.`, 'success'); await renderRoute(); } catch (error) { toast(error.message || 'Unable to update status.', 'error'); } }
function openResetPasswordModal(admin) {
  openModal(`<div class="modal-heading"><span class="admin-eyebrow">Security</span><h2>Reset password</h2><p>Set a new password for ${escapeHtml(displayName(admin))}. They will be signed out of all sessions.</p></div><form id="resetPwForm"><label class="field-label"><span>New password</span><input id="rpNew" type="password" minlength="12" required /></label><label class="field-label" style="margin-top:12px"><span>Confirm password</span><input id="rpConfirm" type="password" minlength="12" required /></label><p class="table-secondary" style="margin-top:8px">Minimum 12 characters with upper, lower, number and symbol.</p><div class="form-actions"><button type="button" class="admin-secondary" data-modal-close>Cancel</button><button class="admin-primary" type="submit">Reset password</button></div></form>`, () => {
    $('#resetPwForm').addEventListener('submit', async event => { event.preventDefault(); const newPassword = $('#rpNew').value; if (newPassword !== $('#rpConfirm').value) { toast('Passwords do not match.', 'error'); return; } const button = event.submitter; setLoading(button, true, 'Resetting…'); try { await $admin(`/admin/admins/${admin.id}/reset-password`, { method: 'POST', body: JSON.stringify({ newPassword }) }); closeModal(); toast('Password reset. The admin must sign in again.', 'success'); } catch (error) { toast(error.message || 'Unable to reset password.', 'error'); } finally { setLoading(button, false); } });
  });
}
function permissionPanelMarkup() {
  return `<div class="perm-panel"><h3 style="margin:0 0 4px;font-size:1rem">Permissions</h3><p class="table-secondary" style="margin:0 0 16px">Toggle individual capabilities. Saving makes this set authoritative for the admin.</p>
  ${permissionCatalog.map(group => `<div class="perm-group" data-perm-group="${escapeAttr(group.group)}"><div class="perm-group-head"><strong>${escapeHtml(group.group)}</strong><div class="perm-group-actions"><button type="button" class="text-btn" data-perm-all="${escapeAttr(group.group)}">Enable all</button><button type="button" class="text-btn" data-perm-none="${escapeAttr(group.group)}">Disable all</button></div></div><div class="perm-items">${group.permissions.map(item => `<label class="perm-item"><input type="checkbox" data-perm="${escapeAttr(item.key)}" ${adminSelectedPerms.has(item.key) ? 'checked' : ''}/><span class="perm-copy"><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.description)}</small></span><span class="switch" aria-hidden="true"></span></label>`).join('')}</div></div>`).join('')}
  </div>`;
}
function refreshPermissionToggles() { $$('[data-perm]').forEach(checkbox => { checkbox.checked = adminSelectedPerms.has(checkbox.dataset.perm); }); }
function bindPermissionPanel() {
  $$('[data-perm]').forEach(checkbox => checkbox.addEventListener('change', () => { checkbox.checked ? adminSelectedPerms.add(checkbox.dataset.perm) : adminSelectedPerms.delete(checkbox.dataset.perm); }));
  $$('[data-perm-all]').forEach(button => button.addEventListener('click', () => { const group = permissionCatalog.find(item => item.group === button.dataset.permAll); (group?.permissions || []).forEach(item => adminSelectedPerms.add(item.key)); refreshPermissionToggles(); }));
  $$('[data-perm-none]').forEach(button => button.addEventListener('click', () => { const group = permissionCatalog.find(item => item.group === button.dataset.permNone); (group?.permissions || []).forEach(item => adminSelectedPerms.delete(item.key)); refreshPermissionToggles(); }));
}
async function openAdminEditor(admin, focusPermissions = false) {
  await ensurePermissionCatalog();
  adminAvatarUrl = admin?.avatarUrl || '';
  const isNew = !admin;
  if (!isNew) {
    adminSelectedPerms = new Set(Array.isArray(admin.permissions) ? admin.permissions : (admin.effectiveFine || []));
    if (!Array.isArray(admin.permissions) && !admin.effectiveFine) { try { const detail = await safeRequest(`/admin/admins/${admin.id}`); if (!isError(detail)) adminSelectedPerms = new Set(detail.effectiveFine || (detail.admin.permissions || [])); } catch {} }
  } else { adminSelectedPerms = new Set(); }
  const targetIsSuper = admin?.role === 'super_admin';
  const accountFields = `<div class="form-grid">
    <label class="field-label"><span>Full name</span><input id="admFullName" required value="${escapeAttr(admin?.fullName || '')}"/></label>
    <label class="field-label"><span>Email (login)</span><input id="admEmail" type="email" required value="${escapeAttr(admin?.email || '')}"/></label>
    <label class="field-label"><span>Phone</span><input id="admPhone" value="${escapeAttr(admin?.phone || '')}"/></label>
    <label class="field-label"><span>Role</span><select id="admRole"><option value="staff" ${admin?.role === 'staff' ? 'selected' : ''}>Staff</option><option value="admin" ${(!admin || admin?.role === 'admin') ? 'selected' : ''}>Admin</option><option value="manager" ${admin?.role === 'manager' ? 'selected' : ''}>Manager</option><option value="support" ${admin?.role === 'support' ? 'selected' : ''}>Support</option><option value="content_manager" ${admin?.role === 'content_manager' ? 'selected' : ''}>Content Manager</option><option value="finance" ${admin?.role === 'finance' ? 'selected' : ''}>Finance</option></select></label>
    <label class="field-label"><span>Status</span><select id="admStatus"><option value="active" ${(!admin || admin?.status === 'active') ? 'selected' : ''}>Active</option><option value="suspended" ${admin?.status === 'suspended' ? 'selected' : ''}>Suspended</option><option value="blocked" ${admin?.status === 'blocked' ? 'selected' : ''}>Disabled</option></select></label>
    <label class="field-label"><span>Profile image</span><input id="admAvatar" type="file" accept="image/jpeg,image/png,image/webp"/></label>
    ${isNew ? `<label class="field-label"><span>Password</span><input id="admPassword" type="password" minlength="12" required /></label><label class="field-label"><span>Confirm password</span><input id="admConfirm" type="password" minlength="12" required /></label>` : ''}
  </div>`;
  openModal(`<div class="modal-heading"><span class="admin-eyebrow">Admin accounts</span><h2>${isNew ? 'Add admin' : 'Edit admin'}</h2></div><form id="adminAccountForm">${accountFields}${targetIsSuper && !isNew ? '<p class="table-secondary" style="margin:14px 0 0">Super Admin has unrestricted access — permissions cannot be limited.</p>' : permissionPanelMarkup()}<div class="form-actions"><span class="form-status" id="adminFormStatus"></span><button type="button" class="admin-secondary" data-modal-close>Cancel</button><button class="admin-primary" type="submit">${isNew ? 'Create admin' : 'Save admin'}</button></div></form>`, () => {
    bindPermissionPanel();
    if (focusPermissions) document.querySelector('.perm-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    $('#admAvatar')?.addEventListener('change', async event => { const file = event.target.files?.[0]; if (!file) return; try { const media = await uploadMediaFile(file, 'logos', $('#admFullName').value); adminAvatarUrl = media.secureUrl; toast('Profile image uploaded.', 'success'); } catch (error) { toast(error.message || 'Upload failed.', 'error'); event.target.value = ''; } });
    $('#adminAccountForm').addEventListener('submit', async event => {
      event.preventDefault();
      const status = $('#adminFormStatus'); if (status) status.textContent = 'Saving…';
      const button = event.submitter; setLoading(button, true, 'Saving…');
      const payload = { fullName: $('#admFullName').value.trim(), email: $('#admEmail').value.trim().toLowerCase(), phone: $('#admPhone').value.trim() || undefined, role: $('#admRole').value, status: $('#admStatus').value, permissions: [...adminSelectedPerms] };
      if (adminAvatarUrl) payload.avatarUrl = adminAvatarUrl;
      try {
        if (isNew) {
          if ($('#admPassword').value !== $('#admConfirm').value) { toast('Passwords do not match.', 'error'); setLoading(button, false); if (status) status.textContent = ''; return; }
          payload.password = $('#admPassword').value;
          await $admin('/admin/admins', { method: 'POST', body: JSON.stringify(payload) });
          toast('Admin account created.', 'success');
        } else {
          await $admin(`/admin/admins/${admin.id}`, { method: 'PATCH', body: JSON.stringify(payload) });
          toast('Admin updated. Permissions saved.', 'success');
        }
        resetDirty(); closeModal(); await renderRoute();
      } catch (error) { toast(error.message || 'Unable to save admin.', 'error'); if (status) status.textContent = ''; }
      finally { setLoading(button, false); }
    });
  });
}

initAuthScene(); bindAuth(); hydrateIcons(); bindShell();
void $admin('/auth/me', {}, false).then(response => { state.currentAdmin = response.user; return loadWorkspace(false); }).catch(() => { /* Login screen remains visible. */ });

